# aicrew message catalog, English (default). One `case` branch per key; arguments are $2.. after the key.
msg_en() {
  local k="$1"; shift
  case "$k" in
    lang.selftest) printf 'language: English' ;;
    lang.args) printf 'two args: %s and %s' "$@" ;;
    gate.repo_unknown) printf 'repository could not be determined' ;;
    gate.pr_unreadable) printf 'PR #%s could not be read (REST)' "$@" ;;
    gate.not_merged) printf 'PR #%s is not MERGED yet (%s)' "$@" ;;
    gate.merged_in_dst) printf 'PR #%s (%s) is in %s' "$@" ;;
    gate.merged_not_in_dst) printf 'PR #%s is merged but %s is not in %s' "$@" ;;
    gate.pr_base) printf 'PR #%s base: %s' "$@" ;;
    gate.multi_close_kw) printf 'one keyword only closes one issue; write one '\''Closes #n'\'' per line' ;;
    gate.base_mismatch) printf 'base %s != %s; run: gh pr edit %s --base %s' "$@" ;;
    gate.head_unreadable) printf 'PR #%s head could not be read' "$@" ;;
    gate.pr_labels_unreadable) printf 'PR #%s labels could not be read' "$@" ;;
    gate.timeline_unreadable) printf 'PR #%s timeline could not be read (REST); closingIssuesReferences cannot be checked when GraphQL is exhausted' "$@" ;;
    gate.sidebar_link_gql_exhausted) printf 'PR #%s has a sidebar link (Development) that cannot be parsed via REST when GraphQL is exhausted; wait for reset and retry' "$@" ;;
    gate.cross_ref_gql_exhausted) printf 'PR #%s closes an issue via URL or owner/repo#N which cannot be checked when GraphQL is exhausted; wait for reset and retry' "$@" ;;
    gate.gql_exhausted_body_fallback) printf 'GraphQL exhausted; issues closed by the PR are read from all #N in the PR body (without sidebar links)' ;;
    gate.closing_refs_unreadable) printf 'PR #%s closingIssuesReferences could not be read' "$@" ;;
    gate.issue_labels_unreadable) printf 'issue #%s labels could not be read' "$@" ;;
    gate.issue_body_unreadable) printf 'body of issue #%s could not be read' "$@" ;;
    gate.owner_only_auto) printf 'PR closes issue(s)%s whose criteria are marked owner only; write Refs #N instead of Closes #N, or let the owner merge' "$@" ;;
    gate.owner_only_warn) printf 'PR closes issue(s)%s whose criteria are marked owner only; the owner follow-up is lost when the issue closes' "$@" ;;
    gate.pr_branch_unreadable) printf 'PR branch could not be read' ;;
    gate.hold_branch_labels_unreadable) printf 'owner-hold: issue #%s labels could not be read (REST)' "$@" ;;
    gate.hold_branch_issue) printf 'owner-hold: issue #%s is held by the owner' "$@" ;;
    gate.hold_pr) printf 'owner-hold: automatic merge requires the owner to release the hold' ;;
    gate.invalid_dst_branch) printf 'target branch '\''%s'\'' contains invalid characters' "$@" ;;
    gate.pr_files_unreadable) printf 'PR #%s file list could not be read' "$@" ;;
    gate.pr_files_unparseable) printf 'PR #%s file list could not be parsed' "$@" ;;
    gate.pr_files_accumulate) printf 'PR files could not be accumulated' ;;
    gate.touches_workflow) printf 'PR touches docs/WORKFLOW.md; auto-merge refused (temporary grants are owner-only); ask the owner to merge' ;;
    gate.too_many_files) printf 'PR has more than 3000 files; auto-merge refused' ;;
    gate.l2_default_branch_unreadable) printf 'risk:L2: auto-merge refused; default branch could not be read (grant not evaluated)' ;;
    gate.l2_workflow_unreadable) printf 'risk:L2: auto-merge refused; docs/WORKFLOW.md could not be read on %s (grant not evaluated)' "$@" ;;
    gate.l2_no_grant) printf 'risk:L2: auto-merge refused; ask the owner to merge (no valid unexpired temporary grant for %s)' "$@" ;;
    gate.temp_grant) printf 'temporary grant: %s (merge before expires above; re-run the gate right before merge)' "$@" ;;
    gate.compare_failed) printf 'cannot check whether PR is behind %s (REST compare failed; fork PRs are not auto-merged)' "$@" ;;
    gate.behind_by_unreadable) printf 'behind_by from compare %s...%s could not be read' "$@" ;;
    gate.pr_behind) printf 'PR is %s commit(s) behind %s; update the branch (merge %s into the PR branch) and wait for CI on the new head; green CI on an old head does not prove the merge result' "$@" ;;
    gate.check_runs_unreadable) printf 'CI check-runs for head %s could not be read (REST)' "$@" ;;
    gate.unnamed_check_run) printf 'unnamed CI check-run found for head %s; cannot be evaluated' "$@" ;;
    gate.workflow_runs_unreadable) printf 'workflow runs for head %s could not be read (REST)' "$@" ;;
    gate.open_runs_count_unreadable) printf 'unfinished workflow run count for head %s could not be read' "$@" ;;
    gate.ci_runs_in_progress) printf 'CI has not finished for head %s (%s workflow run(s) still running); wait and retry' "$@" ;;
    gate.workflows_unreadable) printf 'workflow list could not be read (CI cannot be verified)' ;;
    gate.workflows_total_unreadable) printf 'workflow total could not be read (CI cannot be verified)' ;;
    gate.ci_not_started) printf 'CI has not started for head %s (%s workflow(s) registered, no check-runs yet); wait and retry' "$@" ;;
    gate.ci_classify_failed) printf 'CI classification for head %s failed' "$@" ;;
    gate.ci_non_green_conclusion) printf 'CI for head %s has a check with a non-green conclusion (e.g. action_required or stale)' "$@" ;;
    gate.ci_no_successful_check) printf 'CI for head %s has no successful check (all skipped or neutral)' "$@" ;;
    gate.ci_pending) printf 'CI has not finished for head %s; wait and retry' "$@" ;;
    gate.ci_infra_prefix) printf 'CI cannot start (infrastructure, not a code failure): %s' "$@" ;;
    gate.ci_infra_mixed_checks) printf '%s; other checks are unfinished, cancelled, action_required, or failed from an app other than GitHub Actions: local suite cannot replace CI' "$@" ;;
    gate.ci_failed) printf 'CI failed for head %s' "$@" ;;
    gate.ci_classify_unknown) printf 'unknown CI classification for head %s' "$@" ;;
    gate.pr_behind_warn) printf 'PR is %s commit(s) behind %s; CI on this head does not test the merge result against current %s' "$@" ;;
    gate.pr_comments_unreadable) printf 'PR #%s comments could not be read (REST)' "$@" ;;
    gate.test_approval_eval_failed) printf 'Owner test-change approvals could not be evaluated' ;;
    gate.test_approval_required) printf 'Existing test changes require approval: %s\nOwner approval (scope: test-change <path>[, <path>...]): <text> (Commit: <sha>)' "$@" ;;
    gate.ci_infra_default_branch_unreadable) printf '%s; default branch could not be read (ci-local grant not evaluated)' "$@" ;;
    gate.ci_infra_workflow_unreadable) printf '%s; docs/WORKFLOW.md could not be read on %s (ci-local grant not evaluated)' "$@" ;;
    gate.ci_infra_no_replacement) printf '%s; fix the account/runner and retry, or have the owner write grant '\''- Grant: scope=ci-local; branch=%s; expires=...'\'' in WORKFLOW.md on %s AND comment '\''Laporan ci-lokal: lulus Commit: <sha head>'\'' (full local suite for this head)' "$@" ;;
    gate.ci_replaced_by_local) printf 'CI replaced by local suite for head %s (grant: %s); CI does not prove this result' "$@" ;;
    gate.needs_security) printf 'needs-security: requires a '\''Laporan security: lulus'\'' comment with '\''Commit: <sha head>'\'' from aicrew-security, written by OWNER/MEMBER/COLLABORATOR (two lines, or one line: '\''Laporan security: lulus Commit: <sha head>'\''; case-insensitive)' ;;
    gate.needs_perf) printf 'needs-perf: requires '\''Laporan perf: lulus'\'' with Angka sebelum/sesudah (with digits), Tuning, and '\''Commit: <sha head>'\'' from aicrew-perf, or an owner waiver for the head' ;;
    gate.needs_qa) printf 'non-documentation-only PR: requires a '\''Laporan qa: lulus'\'' comment from aicrew-qa with '\''Commit: <sha head>'\'' (two lines, or one line: '\''Laporan qa: lulus Commit: <sha head>'\''; case-insensitive); latest verdict for the head wins' ;;
    gate.issue_comments_unreadable) printf 'issue #%s comments could not be read (REST); owner decisions cannot be checked' "$@" ;;
    gate.issue_comments_unparseable) printf 'issue #%s comments could not be parsed' "$@" ;;
    gate.owner_decision_eval_failed) printf 'owner decisions could not be evaluated' ;;
    gate.owner_decision_pending) printf 'unacknowledged owner decision after latest verdict for head: %s; apply it, then have the PR author comment '\''Decision applied: <summary>'\'' (and get a new verdict if head changes)' "$@" ;;
    gate.diff_unreadable) printf 'PR #%s diff could not be read (REST)' "$@" ;;
    gate.baseline_secret) printf 'baseline-scan found a secret in the diff; fix it, or add an owner waiver (rahasia) for the PR head' ;;
    gate.cve_repo_unknown) printf 'cve: repository could not be determined' ;;
    gate.cve_files_unreadable) printf 'cve: PR #%s file list could not be read (REST)' "$@" ;;
    gate.cve_workflow_unreadable) printf 'cve: docs/WORKFLOW.md could not be read on target branch (REST); private package patterns unknown' ;;
    gate.cve_disabled) printf 'CVE check is disabled in WORKFLOW.md' ;;
    gate.cve_manifest_missing_head) printf 'cve: %s not found at head (REST) even though it was not removed' "$@" ;;
    gate.cve_manifest_unreadable_head) printf 'cve: %s could not be read at head (REST)' "$@" ;;
    gate.cve_manifest_unreadable_base) printf 'cve: %s could not be read at merge-base (REST)' "$@" ;;
    gate.cve_npmrc_unreadable) printf 'cve: %s could not be read on target branch (REST); private package patterns unknown' "$@" ;;
    gate.cve_new_private_pattern) printf 'cve (%s) new private pattern only takes effect after merge; matching packages in this PR are still queried' "$@" ;;
    gate.cve_private_skipped) printf 'cve (%s) %s private package(s) not checked' "$@" ;;
    gate.cve_new_vuln) printf 'cve: new HIGH/CRITICAL/UNKNOWN dependency vulnerability; upgrade as suggested above, or add an owner waiver (cve) for the PR head' ;;
    gate.cve_osv_unreachable) printf 'cve: OSV unreachable for a PR touching a manifest; retry later, or add an owner waiver (cve) for the PR head' ;;
    gate.sched_check_failed) printf 'scheduled workflows could not be checked' ;;
    gate.sched_default_branch_unreadable) printf 'scheduled workflows could not be checked (default branch could not be read)' ;;
    gate.sched_inactive_until_default) printf 'scheduled workflow %s is inactive until merged into the default branch (%s)' "$@" ;;
    gate.missing_release_note) printf 'PR is missing a '\''Release note:'\'' line (docs/WORKFLOW.md on %s uses CHANGELOG.md); write '\''Release note: <Added|Changed|Fixed|Security> - <text>'\'' or '\''Release note: -'\'' if internal' "$@" ;;
    gate.passed) printf 'gate passed for head %s. Merge with: gh pr merge %s --match-head-commit %s' "$@" ;;
    autopilot.unknown_arg) printf 'unknown argument: %s' "$@" ;;
    autopilot.already_running) printf 'autopilot already running (pid %s, started %s)' "$@" ;;
    autopilot.lock_failed) printf 'autopilot: cannot take lock %s' "$@" ;;
    autopilot.last_completed) printf 'round %s: last completed: #%s (%s)' "$@" ;;
    autopilot.round_summary) printf 'round %s: summary: duration %ss; rc=%s; merged PRs: %s; open PRs: %s; total %s' "$@" ;;
    autopilot.round_summary_gh_err) printf 'round %s: summary: duration %ss; rc=%s; PRs unreadable (gh failed); total %s' "$@" ;;
    autopilot.owner_actions_suffix) printf '; owner actions: %s' "$@" ;;
    autopilot.board_sync_failed) printf 'board: --sync failed (ignored)' ;;
    autopilot.board_sync_cards_failed) printf 'board: --sync-cards failed (ignored)' ;;
    autopilot.no_session_persistence) printf 'round %s: --no-session-persistence in AICREW_CLAUDE_ARGS (transcript not written); idle watchdog disabled for this round, --round-timeout still applies' "$@" ;;
    autopilot.transcript_dir_missing) printf 'round %s: transcript directory not found (%s); idle watchdog disabled for this round' "$@" ;;
    autopilot.reason_round_timeout) printf 'round timeout (%s seconds)' "$@" ;;
    autopilot.reason_idle) printf 'idle %s minutes' "$@" ;;
    autopilot.interrupted_sigint) printf 'round %s: %s; interrupted (SIGINT)' "$@" ;;
    autopilot.still_alive_after_sigint) printf 'round %s: session still alive %s seconds after SIGINT; waiting %s more seconds' "$@" ;;
    autopilot.sent_sigterm) printf 'round %s: session did not exit; sent SIGTERM' "$@" ;;
    autopilot.still_stuck) printf 'autopilot: still stuck: state unchanged since %s; changed inputs: none; no round run (change an issue/PR, WORKFLOW.md or permission files, or pass --retry-stuck)' "$@" ;;
    autopilot.gh_unreadable_retry) printf 'round %s: gh unreadable (attempt %s/5): state unknown, not deciding done or waiting' "$@" ;;
    autopilot.gh_down_stop) printf 'autopilot: gh unreadable 5 times in a row; stopping (not an issue state), check network and gh auth' ;;
    autopilot.all_done) printf 'autopilot: all issues done (round %s)' "$@" ;;
    autopilot.all_await_owner) printf 'autopilot: all %s remaining issues await the owner (needs-principal, blocked or owner-hold)' "$@" ;;
    autopilot.max_total_reached) printf 'autopilot: %s; cumulative total across runs, reset with --reset-total or remove .aicrew/total' "$@" ;;
    autopilot.waiting_owner) printf 'autopilot: waiting for owner (%s issues: needs-principal, blocked, owner-hold or an open PR awaiting merge); check every %s minutes, limit %s days' "$@" ;;
    autopilot.wait_timeout) printf 'autopilot: waiting for owner exceeded the %s-day limit; stopping' "$@" ;;
    autopilot.wait_resumed) printf 'autopilot: change detected while waiting (e.g. merge by owner); resuming rounds' ;;
    autopilot.round_start) printf 'round %s: %s open issue(s) (%s waiting for owner)' "$@" ;;
    autopilot.in_progress) printf 'round %s: in progress: %s' "$@" ;;
    autopilot.round_rc) printf 'round %s: rc=%s' "$@" ;;
    autopilot.watchdog_ended) printf 'round %s: ended by idle watchdog (rc normalized); issue list will be reloaded in the next round' "$@" ;;
    autopilot.limit_wait) printf 'autopilot: usage limit hit, waiting %s minutes before retrying' "$@" ;;
    autopilot.limit_false_positive) printf 'round %s: output mentions limit but rc=0 and report is long (%s lines); treated as normal (not a limit)' "$@" ;;
    autopilot.limit_resumed) printf 'autopilot: resuming after limit' ;;
    autopilot.round_failed) printf 'round %s: failed rc=%s (%s in a row), see %s' "$@" ;;
    autopilot.consecutive_failures) printf 'autopilot: 3 consecutive rounds failed (rc=%s); stopping, see %s' "$@" ;;
    autopilot.stuck) printf 'autopilot: stuck, %s rounds with no issue/PR changes; stopping' "$@" ;;
    autopilot.fingerprint_unreadable) printf 'round %s: fingerprint unreadable (gh failed); not counted as progress or stuck; pausing before next round' "$@" ;;
    autopilot.max_rounds_reached) printf 'autopilot: round limit (%s) reached' "$@" ;;
    autostart.usage) printf 'usage: autostart.sh install|uninstall|status|resume|run <repo> [options]' ;;
    autostart.dir_missing) printf 'directory does not exist: %s' "$@" ;;
    autostart.unknown_arg) printf 'unknown argument: %s' "$@" ;;
    autostart.max_total_required) printf 'install: --max-total N (integer > 0) is required as a cost limit for unattended loops' ;;
    autostart.interval_min) printf 'install: --interval must be at least 60 seconds' ;;
    autostart.not_git_repo) printf 'install: %s is not a git repository' "$@" ;;
    autostart.permissions_missing) printf 'install: autopilot permissions are not installed in %s/.claude/settings.local.json; run first (in the project folder): bash %s/install-permissions.sh' "$@" ;;
    autostart.bin_missing) printf 'install: '\''%s'\'' not found in PATH' "$@" ;;
    autostart.invalid_plist) printf 'install: invalid plist' ;;
    autostart.bootstrap_failed) printf 'install: launchctl bootstrap failed (plist at %s)' "$@" ;;
    autostart.installed) printf 'autostart: installed %s (every %s minutes and at login; --max-total %s). Brake: touch %s/PAUSE. Remove: autostart.sh uninstall %s' "$@" ;;
    autostart.uninstalled) printf 'autostart: uninstalled %s (state in %s kept)' "$@" ;;
    autostart.status_label) printf 'label: %s' "$@" ;;
    autostart.status_installed_yes) printf 'installed: yes (%s)' "$@" ;;
    autostart.status_installed_no) printf 'installed: no' ;;
    autostart.status_loaded_yes) printf 'loaded in launchd: yes' ;;
    autostart.status_loaded_no) printf 'loaded in launchd: no' ;;
    autostart.status_halted_yes) printf 'halted: yes (%s); inspect then run: autostart.sh resume %s' "$@" ;;
    autostart.status_halted_no) printf 'halted: no' ;;
    autostart.status_pause_yes) printf 'PAUSE: yes' ;;
    autostart.status_pause_no) printf 'PAUSE: no' ;;
    autostart.status_lock_pid) printf 'lock: pid %s' "$@" ;;
    autostart.status_lock_none) printf 'lock: none' ;;
    autostart.status_last_log) printf 'recent log:' ;;
    autostart.resumed) printf 'autostart: halted and stuck markers removed; the next tick will run autopilot again' ;;
    autostart.pause_skipped) printf 'PAUSE: skipped' ;;
    autostart.max_total_empty) printf 'AICREW_MAX_TOTAL is empty: refused (no cost limit)' ;;
    autostart.gh_unavailable) printf 'gh/network unavailable: skipped' ;;
    autostart.already_running) printf 'another autopilot is running (pid %s): skipped' "$@" ;;
    autostart.lock_failed) printf 'failed to acquire lock' ;;
    autostart.starting) printf 'starting autopilot (--max-total %s)' "$@" ;;
    autostart.finished) printf 'autopilot finished rc=%s' "$@" ;;
    autostart.halted_notify) printf 'autostart %s: halted (rc=%s), will not run automatically again. Inspect %s/autopilot.log then run: autostart.sh resume %s' "$@" ;;
    autostart.unknown_cmd) printf 'unknown command: %s' "$@" ;;
    owner.needs_principal) printf '#%s %s — answer the question in the issue, then remove the label — `gh issue edit %s --remove-label needs-principal` — an owner decision; an agent must not decide it' "$@" ;;
    owner.owner_hold) printf '#%s %s — owner-hold: only the owner may release this hold — `gh issue edit %s --remove-label owner-hold`' "$@" ;;
    owner.blocked) printf '%s blocked: %s — resolve the cause, then remove the label — `gh issue edit %s --remove-label blocked`' "$@" ;;
    owner.pr_merge) printf 'PR #%s (issue #%s) %s — review and merge — `gh pr merge %s --merge --match-head-commit %s` — %s' "$@" ;;
    owner.reason_l2) printf 'risk:L2 is never merged automatically' ;;
    owner.reason_security) printf 'security review is pending' ;;
    owner.reason_merge_mode) printf 'the merge mode needs the owner' ;;
    owner.header) printf '# Owner actions (%s)' "$@" ;;
    owner.agent_note) printf 'agent note: %s' "$@" ;;
    owner.ci_infra) printf 'PR #%s — %s' "$@" ;;
    owner.none) printf 'No owner actions found.' ;;
    owner.summary) printf '%s (%s item(s))' "$@" ;;
    budget.max_iter) printf 'STOP: iteration limit (%s) reached' "$@" ;;
    budget.max_fail) printf 'STOP: issue %s failed %s times' "$@" ;;
    budget.max_total) printf 'STOP: total %s >= %s (--max-total)' "$@" ;;
    budget.continue) printf 'continue' ;;
    budget.usage) printf 'usage: budget.sh iter|newrun|fail N|reset N|check maxIter maxFail [N] [maxTotal]' ;;
    notify.default) printf 'needs attention' ;;
    blocked.mark_usage) printf 'usage: blocked-mark.sh <issue-number> <reason>' ;;
    blocked.cannot_read) printf 'blocked-mark: cannot read #%s' "$@" ;;
    blocked.already) printf '#%s already blocked' "$@" ;;
    blocked.label_desc) printf 'cannot advance without outside action' ;;
    blocked.marked) printf '#%s marked blocked' "$@" ;;
    blocked.note_usage) printf 'usage: blocked-note.sh <pr> <command>' ;;
    blocked.note_allow_hint) printf 'Add to permissions.allow in .claude/settings.local.json: "Bash(%s:*)"' "$@" ;;
    *) return 1 ;;
  esac
}
